import "./styles/skeuo-input.css";
import type { InputHTMLAttributes, TextareaHTMLAttributes } from "react";
export function SkeuoInput({ className = "", ...props }: InputHTMLAttributes<HTMLInputElement>) {
  return <input data-sk-root="" className={`sk-input ${className}`} {...props} />;
}
export function SkeuoTextarea({ className = "", ...props }: TextareaHTMLAttributes<HTMLTextAreaElement>) {
  return <textarea data-sk-root="" className={`sk-input sk-textarea ${className}`} {...props} />;
}

@import "./skeuo-base.css";
.sk-input{ display: block; width: 100%; min-width: 0; padding: 12px 14px; border: 1px solid var(--sk-edge); border-radius: 6px; background: var(--sk-well); color: var(--sk-ink); box-shadow: inset 0 3px 6px var(--sk-shadow),inset 1px 1px 2px var(--sk-shadow),0 1px 0 var(--sk-highlight); font: inherit; font-size: 13px; line-height: 1.7; }
.sk-input::placeholder{ color: var(--sk-muted); }
.sk-input:focus-visible{ outline: 2px solid var(--sk-accent); outline-offset: 3px; }
.sk-input:disabled{ opacity: .55; cursor: not-allowed; }
.sk-textarea{ min-height: 130px; resize: vertical; }
@media(max-width:600px){.sk-input{ font-size: 16px; }}

.sk-input {font-family:var(--sk-font-sans,system-ui,sans-serif);}

@import "./skeuo-tokens.css";
:where([data-sk-root],[data-sk-root] *) {box-sizing:border-box;}
:where([data-sk-root]) {font-family:var(--sk-font-sans,system-ui,sans-serif);font-size:14px;line-height:1.5;color:var(--sk-ink);}
:where([data-sk-root] button,[data-sk-root] input,[data-sk-root] textarea) {font:inherit;}
:where([data-sk-root] :is(h1,h2,h3,h4,p,figure,blockquote,ul)) {margin:0;}
:where([data-sk-root] button) {cursor:pointer;}
:where([data-sk-root] :focus-visible) {outline:2px solid var(--sk-accent);outline-offset:3px;}
:where([data-sk-root] button:disabled) {cursor:not-allowed;}

/* Namespaced defaults. Host applications can override any --sk-* token. */
:where(:root,.light,[data-theme="light"]) {
  --sk-album-paper:#faf9f5;--sk-album-ink:#45423b;--sk-album-edge:#c4c2ba;--sk-album-base:#d6d4ca;
  --sk-bg: #fff; --sk-ink: #202020; --sk-muted: #777774; --sk-line: #e7e7e4;
  --sk-surface: #f5f5f2; --sk-surface-raised: #fafaf8; --sk-well: #e9e9e5;
  --sk-edge: #d1d1cb; --sk-highlight: #fff; --sk-base: #d9d9d3; --sk-shadow: #00000017;
  --sk-accent: #365e50; --sk-accent-bright: #487b68; --sk-accent-base: #213c32; --sk-accent-edge: #294b3e; --sk-accent-ink: #fff;
  --sk-key: #f9f9f7; --sk-key-edge: #c6c7c1; --sk-key-base: #d0d1ca;
  --sk-font-mono: ui-monospace, SFMono-Regular, Consolas, monospace; --sk-font-sans: system-ui, sans-serif;

}
:where(.dark,[data-theme="dark"]) {
  --sk-album-paper:#272728;--sk-album-ink:#d0cfca;--sk-album-edge:#555456;--sk-album-base:#111214;
  --sk-bg: #000; --sk-ink: #efefeb; --sk-muted: #92928d; --sk-line: #242424;
  --sk-surface: #191919; --sk-surface-raised: #252525; --sk-well: #111;
  --sk-edge: #3b3b39; --sk-highlight: #ffffff1e; --sk-base: #080808; --sk-shadow: #00000099;
  --sk-accent: #9ab5a6; --sk-accent-bright: #bbcec2; --sk-accent-base: #4d6558; --sk-accent-edge: #6f8a79; --sk-accent-ink: #14251c;
  --sk-key: #292a29; --sk-key-edge: #484946; --sk-key-base: #101110;

}
@media(prefers-color-scheme:dark) { :where(html:not(.light):not(.dark):not([data-theme])) {
  --sk-album-paper:#272728;--sk-album-ink:#d0cfca;--sk-album-edge:#555456;--sk-album-base:#111214;
  --sk-bg: #000; --sk-ink: #efefeb; --sk-muted: #92928d; --sk-line: #242424;
  --sk-surface: #191919; --sk-surface-raised: #252525; --sk-well: #111;
  --sk-edge: #3b3b39; --sk-highlight: #ffffff1e; --sk-base: #080808; --sk-shadow: #00000099;
  --sk-accent: #9ab5a6; --sk-accent-bright: #bbcec2; --sk-accent-base: #4d6558; --sk-accent-edge: #6f8a79; --sk-accent-ink: #14251c;
  --sk-key: #292a29; --sk-key-edge: #484946; --sk-key-base: #101110;

} }
